"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[52945],{82142:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"HealthStaminaGuiController","desc":"Drives the segmented `HealthStaminaGui` HUD from\\n`Signals.OnHealthValueChanged(health, shield)` and\\n`Signals.OnStaminaValueChanged(stamina)`.\\n\\nEach bar is 10 equal cells; one cell = 10 % of the current max. Cell i shows\\n`clamp(value / max * 10 - (i - 1), 0, 1)` as the X scale of its `Fill`.\\n\\n```\\nMainContainer (UICorner, UIStroke, UIScale)\\n\u251c\u2500\u2500 DecoLayer { Rail, Dot1, Dot2, Dot3, Tail, Tick }   -- pulse red when critical\\n\u2514\u2500\u2500 Content (UIPadding, UIListLayout)\\n    \u2514\u2500\u2500 Gauge (UIListLayout horizontal)\\n        \u251c\u2500\u2500 Labels { HP, ShieldSpacer, ST }\\n        \u251c\u2500\u2500 Well (UIStroke: red when critical, UIPadding)\\n        \u2502   \u251c\u2500\u2500 HealthCells  Cell1..10 { Ghost, Fill { Shade } }\\n        \u2502   \u251c\u2500\u2500 ShieldCells  Cell1..10 { Fill }       -- Visible only with shield\\n        \u2502   \u2514\u2500\u2500 StaminaCells Cell1..10 { Fill { Shade }, TiredStroke }\\n        \u2514\u2500\u2500 Values { HealthText, ShieldSpacer, StaminaText }\\n```\\n\\n`Ghost` is the damage chip: on damage it holds the old HP for\\n`GHOST_HOLD` seconds, then eases down to the new HP. Below `CRITICAL_RATIO`\\nthe well stroke, deco frames and HP fills pulse. At 0 stamina the value reads\\n\\"TIRED\\". Phone-sized screens switch to the compact layout (top-left, under\\nthe chat button). Names are load-bearing; keep them in sync with Studio.","realm":["Client"],"source":{"line":34,"path":"src/StarterPlayer/StarterPlayerScripts/HealthStaminaGuiController.client.luau"}}')}}]);